     1→package com.global.ct.frameinventory.frame;
     2→
     3→import lombok.RequiredArgsConstructor;
     4→import lombok.extern.slf4j.Slf4j;
     5→import org.springframework.stereotype.Service;
     6→
     7→import java.time.Instant;
     8→import java.util.ArrayList;
     9→import java.util.Collections;
    10→import java.util.List;
    11→import java.util.Objects;
    12→
    13→@Service
    14→@Slf4j
    15→@RequiredArgsConstructor
    16→public class FrameService {
    17→
    18→    private final FrameRepository frameRepository;
    19→
    20→    public List<Frame> findAll() {
    21→        return frameRepository.findAll();
    22→    }
    23→
    24→    public Frame findByFrameId(String frameId) {
    25→        return frameRepository.findByFrameId(frameId)
    26→                .orElseThrow(() -> new FrameNotFoundException(frameId));
    27→    }
    28→
    29→    public Frame create(FrameRequest request) {
    30→        log.info("Creating frame with frameId= {}", request.getFrameId());
    31→        Instant now = Instant.now();
    32→
    33→        Frame frame = new Frame();
    34→        frame.setFrameId(request.getFrameId());
    35→        frame.setType(request.getType());
    36→        frame.setFormat(request.getFormat());
    37→        frame.setEnvironment(request.getEnvironment());
    38→        frame.setStatus(request.getStatus());
    39→        frame.setCreatedDate(now);
    40→        frame.setModifiedDate(now);
    41→
    42→        FrameHistoryEntry historyEntry = FrameHistoryEntry.builder()
    43→                .timestamp(now)
    44→                .action(Action.CREATE)
    45→                .user("system")
    46→                .changes(Collections.emptyList())
    47→                .build();
    48→        frame.getHistory().add(historyEntry);
    49→
    50→        return frameRepository.save(frame);
    51→    }
    52→
    53→    public Frame update(String frameId, FrameRequest request) {
    54→        log.info("Updating frame with frameId= {}", frameId);
    55→        Frame frame = findByFrameId(frameId);
    56→        Instant now = Instant.now();
    57→
    58→        List<ChangedField> changes = detectChanges(frame, request);
    59→
    60→        frame.setType(request.getType());
    61→        frame.setFormat(request.getFormat());
    62→        frame.setEnvironment(request.getEnvironment());
    63→        frame.setStatus(request.getStatus());
    64→        frame.setModifiedDate(now);
    65→
    66→        if (!changes.isEmpty()) {
    67→            FrameHistoryEntry historyEntry = FrameHistoryEntry.builder()
    68→                    .timestamp(now)
    69→                    .action(Action.UPDATE)
    70→                    .user("system")
    71→                    .changes(changes)
    72→                    .build();
    73→            frame.getHistory().add(historyEntry);
    74→        }
    75→
    76→        return frameRepository.save(frame);
    77→    }
    78→
    79→    private List<ChangedField> detectChanges(Frame frame, FrameRequest request) {
    80→        List<ChangedField> changes = new ArrayList<>();
    81→
    82→        if (!Objects.equals(frame.getType(), request.getType())) {
