    28→    public CsvParseResult parse(MultipartFile file) {
    29→        List<Frame> validFrames = new ArrayList<>();
    30→        List<CsvRowError> errors = new ArrayList<>();
    31→
    32→        try (CSVReader reader = new CSVReader(new InputStreamReader(file.getInputStream()))) {
    33→            String[] header = reader.readNext();
    34→            if (header == null) {
