    62→    private Map<String, Integer> buildColumnIndex(String[] header) {
    63→        Map<String, Integer> index = new HashMap<>();
    64→        for (int i = 0; i < header.length; i++) {
    65→            index.put(header[i].trim().toLowerCase(), i);
