import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { getFrames } from '../api/frames';
import type { Frame } from '../types/frame';

export function FrameListPage() {
  const [frames, setFrames] = useState<Frame[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const navigate = useNavigate();

  useEffect(() => {
    getFrames()
      .then(setFrames)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  function formatDate(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    });
  }

  function getStatusChipClass(status: string): string {
    switch (status.toUpperCase()) {
      case 'LIVE':
        return 'chip success';
      case 'DRAFT':
        return 'chip neutral';
      case 'PENDING':
        return 'chip warning';
      case 'INACTIVE':
        return 'chip error';
      default:
        return 'chip neutral';
    }
  }

  if (loading) {
    return (
      <div style={{ padding: 'var(--sp-4)' }}>
        <p>Loading frames...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: 'var(--sp-4)' }}>
        <p style={{ color: 'var(--error-main)' }}>Error: {error}</p>
      </div>
    );
  }

  return (
    <div style={{ padding: 'var(--sp-4)' }}>
      <header style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: 'var(--sp-3)'
      }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '20px', fontWeight: 600 }}>
            Frames
          </h1>
          <p style={{ margin: '4px 0 0', color: 'var(--text-secondary)', fontSize: '13px' }}>
            {frames.length} {frames.length === 1 ? 'frame' : 'frames'}
          </p>
        </div>
        <div style={{ display: 'flex', gap: 'var(--sp-1)' }}>
          <Link to="/upload" className="btn secondary">
            Upload CSV
          </Link>
          <Link to="/frames/new" className="btn primary">
            New frame
          </Link>
        </div>
      </header>

      {frames.length === 0 ? (
        <div className="surface" style={{ padding: 'var(--sp-4)', textAlign: 'center' }}>
          <p style={{ color: 'var(--text-secondary)' }}>No frames yet.</p>
          <p style={{ marginTop: 'var(--sp-2)' }}>
            <Link to="/frames/new" className="btn primary">Create your first frame</Link>
            {' or '}
            <Link to="/upload" className="btn secondary">Upload a CSV</Link>
          </p>
        </div>
      ) : (
        <div className="surface" style={{ overflow: 'hidden' }}>
          <table className="tbl">
            <thead>
              <tr>
                <th>Frame ID</th>
                <th>Type</th>
                <th>Format</th>
                <th>Environment</th>
                <th>Status</th>
                <th>Modified</th>
              </tr>
            </thead>
            <tbody>
              {frames.map((frame) => (
                <tr
                  key={frame.frameId}
                  onClick={() => navigate(`/frames/${frame.frameId}`)}
                >
                  <td>
                    <span className="id">{frame.frameId}</span>
                  </td>
                  <td>{frame.type}</td>
                  <td>{frame.format || '—'}</td>
                  <td>{frame.environment || '—'}</td>
                  <td>
                    <span className={getStatusChipClass(frame.status)}>
                      <span className="dot"></span>
                      {frame.status}
                    </span>
                  </td>
                  <td>
                    <span className="mono">{formatDate(frame.modifiedDate)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { getFrame } from '../api/frames';
import type { Frame, FrameHistoryEntry } from '../types/frame';

export function FrameDetailPage() {
  const { frameId } = useParams<{ frameId: string }>();
  const [frame, setFrame] = useState<Frame | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!frameId) return;

    getFrame(frameId)
      .then(setFrame)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [frameId]);

  function formatDateTime(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  function getStatusChipClass(status: string): string {
    switch (status.toUpperCase()) {
      case 'LIVE':
        return 'chip success';
      case 'DRAFT':
        return 'chip neutral';
      case 'PENDING':
        return 'chip warning';
      case 'INACTIVE':
        return 'chip error';
      default:
        return 'chip neutral';
    }
  }

  function getTimelineItemClass(entry: FrameHistoryEntry): string {
    return entry.action === 'CREATE' ? 'tl-item create' : 'tl-item';
  }

  function getActionVerb(action: string): string {
    return action === 'CREATE' ? 'created this frame' : 'updated this frame';
  }

  if (loading) {
    return (
      <div style={{ padding: 'var(--sp-4)' }}>
        <p>Loading frame...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: 'var(--sp-4)' }}>
        <p style={{ color: 'var(--error-main)' }}>Error: {error}</p>
        <Link to="/" className="btn outlined" style={{ marginTop: 'var(--sp-2)' }}>
          Back to list
        </Link>
      </div>
    );
  }

  if (!frame) {
    return (
      <div style={{ padding: 'var(--sp-4)' }}>
        <p>Frame not found</p>
        <Link to="/" className="btn outlined" style={{ marginTop: 'var(--sp-2)' }}>
          Back to list
        </Link>
      </div>
    );
  }

  const sortedHistory = [...frame.history].sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  );

  return (
    <div style={{ padding: 'var(--sp-4)' }}>
      <header style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'flex-start',
        marginBottom: 'var(--sp-3)'
      }}>
        <div>
          <div style={{ marginBottom: 'var(--sp-1)' }}>
            <Link to="/" style={{ fontSize: '13px', color: 'var(--text-secondary)' }}>
              ← Back to frames
            </Link>
          </div>
          <h1 style={{ margin: 0, fontSize: '20px', fontWeight: 600, display: 'flex', alignItems: 'center', gap: 'var(--sp-2)' }}>
            <span className="id">{frame.frameId}</span>
            <span className={getStatusChipClass(frame.status)}>
              <span className="dot"></span>
              {frame.status}
            </span>
          </h1>
        </div>
        <Link to={`/frames/${frame.frameId}/edit`} className="btn primary">
          Edit frame
        </Link>
      </header>

      <div className="surface">
        <div className="section-block">
          <h2>Details</h2>
          <div className="kv">
            <div>
              <span className="k">Frame ID</span>
              <span className="v mono">{frame.frameId}</span>
            </div>
            <div>
              <span className="k">Type</span>
              <span className="v">{frame.type}</span>
            </div>
            <div>
              <span className="k">Format</span>
              <span className={`v ${!frame.format ? 'muted' : ''}`}>
                {frame.format || '—'}
              </span>
            </div>
            <div>
              <span className="k">Environment</span>
              <span className={`v ${!frame.environment ? 'muted' : ''}`}>
                {frame.environment || '—'}
              </span>
            </div>
            <div>
              <span className="k">Status</span>
              <span className="v">{frame.status}</span>
            </div>
            <div>
              <span className="k">Created</span>
              <span className="v mono">{formatDateTime(frame.createdDate)}</span>
            </div>
            <div>
              <span className="k">Last Modified</span>
              <span className="v mono">{formatDateTime(frame.modifiedDate)}</span>
            </div>
          </div>
        </div>

        <div className="section-block">
          <h2>History</h2>
          {sortedHistory.length === 0 ? (
            <p style={{ color: 'var(--text-secondary)', fontSize: '13px' }}>
              No history recorded.
            </p>
          ) : (
            <div className="timeline">
              {sortedHistory.map((entry, index) => (
                <div key={index} className={getTimelineItemClass(entry)}>
                  <div className="tl-meta">
                    <span className="who">{entry.user}</span>
                    <span className="verb">{getActionVerb(entry.action)}</span>
                    <span className="when">{formatDateTime(entry.timestamp)}</span>
                  </div>
                  {entry.changes.length > 0 && (
                    <div className="tl-body">
                      {entry.changes.map((change, changeIndex) => (
                        <div key={changeIndex} className="diff-row">
                          <span className="field-name">{change.field}</span>
                          <span className="from">{change.oldValue || '(empty)'}</span>
                          <span className="arrow">→</span>
                          <span className="to">{change.newValue || '(empty)'}</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

