  padding: 8px var(--sp-3);
  display: flex; align-items: center; gap: 16px;
  font-size: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.concept-bar .label { color: rgba(255,255,255,0.6); }
.concept-bar .label b { color: white; font-weight: 600; }
