  filter: drop-shadow(0 2px 3px rgba(0,0,0,0.25));
  cursor: pointer;
}
.fake-map .pin.active { color: var(--error-dark); transform: translate(-50%, -100%) scale(1.25); z-index: 2; }
.fake-map .pin svg { width: 100%; height: 100%; }
.fake-map .legend {
  position: absolute; bottom: 12px; left: 12px;
  background: white;
  border-radius: var(--radius);
  padding: 8px 10px;
  font-size: 11px;
  box-shadow: var(--elev-low);
  display: flex; gap: 12px;
  align-items: center;
}
.fake-map .legend .item { display: flex; align-items: center; gap: 4px; }
.fake-map .legend .dot { width: 8px; height: 8px; border-radius: 50%; }

/* ---------- Master/detail split (Direction B) ---------- */
.split {
  display: grid;
  grid-template-columns: 380px 1fr;
  height: calc(100vh - 56px);
  background: var(--white);
}
.split .list {
  border-right: 1px solid var(--border-subtle);
  overflow: auto;
  display: flex; flex-direction: column;
}
.split .list .list-head {
  padding: var(--sp-2) var(--sp-2);
  border-bottom: 1px solid var(--border-subtle);
  position: sticky; top: 0; background: var(--white); z-index: 2;
}
.split .list .row {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-subtle);
  cursor: pointer;
  display: flex; flex-direction: column; gap: 4px;
}
.split .list .row:hover { background: var(--gray-50); }
.split .list .row.active {
  background: var(--blue-50);
  box-shadow: inset 3px 0 0 var(--primary-main);
}
.split .list .row .head {
  display: flex; justify-content: space-between; align-items: center; gap: 6px;
}
.split .list .row .id { font-family: ui-monospace, Menlo, monospace; font-size: 11px; color: var(--text-secondary); font-weight: 500; }
.split .list .row .title { font-weight: 500; font-size: 13px; color: var(--text-primary); }
.split .list .row .sub   { font-size: 12px; color: var(--text-secondary); }
.split .detail { overflow: auto; background: var(--bg-subtle); }

/* ---------- Filter sidebar (Direction A) ---------- */
.filters {
  width: 264px;
  background: var(--white);
  border-right: 1px solid var(--border-subtle);
  padding: var(--sp-2);
  overflow: auto;
}
.filters h3 {
  font-size: 11px; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.06em;
  color: var(--text-secondary);
  margin: 10px 4px 8px;
}
.filters .fg + .fg { margin-top: var(--sp-2); }
.filters label.opt {
  display: flex; align-items: center; gap: 8px;
  padding: 5px 4px;
  font-size: 13px;
  color: var(--text-primary);
  cursor: pointer;
  border-radius: 4px;
}
.filters label.opt:hover { background: var(--gray-50); }
.filters label.opt input { accent-color: var(--primary-main); }
.filters label.opt .count { margin-left: auto; color: var(--text-secondary); font-size: 11px; }
.filters .range {
  display: flex; gap: 6px; padding: 4px;
