.banner {
  background: var(--blue-50);
  border: 1px solid var(--blue-200);
  border-left: 4px solid var(--primary-main);
  padding: 10px 14px;
  border-radius: var(--radius);
  font-size: 13px;
  color: var(--primary-dark);
  display: flex; gap: 10px; align-items: center;
