}

.back-link {
  display: inline-block;
  margin-bottom: var(--sp-1);
  font-size: 13px;
  color: var(--text-secondary);
}

.btn-group {
  display: flex;
  gap: var(--sp-1);
}

/* ---------- Error states ---------- */
.error-text { color: var(--error-main); }

.error-banner {
  padding: var(--sp-2);
