     1→package com.global.ct.frameinventory.csv;
     2→
     3→import com.global.ct.frameinventory.frame.Frame;
     4→import com.global.ct.frameinventory.frame.FrameService;
     5→import lombok.RequiredArgsConstructor;
     6→import lombok.extern.slf4j.Slf4j;
     7→import org.springframework.stereotype.Service;
     8→import org.springframework.web.multipart.MultipartFile;
     9→
    10→import java.util.ArrayList;
    11→import java.util.List;
    12→
    13→@Service
    14→@Slf4j
    15→@RequiredArgsConstructor
    16→public class CsvUploadService {
    17→
    18→    private final CsvParserService csvParserService;
    19→    private final FrameService frameService;
    20→
    21→    public CsvUploadResult processUpload(MultipartFile file) {
    22→        CsvParserService.CsvParseResult parseResult = csvParserService.parse(file);
    23→        return saveFrames(parseResult.validFrames(), parseResult.errors(), parseResult.totalRows());
    24→    }
    25→
    26→    private CsvUploadResult saveFrames(List<Frame> frames, List<CsvRowError> parseErrors, int totalRows) {
    27→        log.info("Processing {} frames from CSV upload", frames.size());
    28→
    29→        List<CsvRowError> allErrors = new ArrayList<>(parseErrors);
    30→        int insertedCount = 0;
    31→        int skippedCount = 0;
    32→
    33→        for (Frame frame : frames) {
    34→            if (frameService.existsByFrameId(frame.getFrameId())) {
    35→                skippedCount++;
    36→                log.debug("Skipping duplicate frameId: {}", frame.getFrameId());
    37→            } else {
    38→                try {
    39→                    frameService.save(frame);
    40→                    insertedCount++;
    41→                } catch (Exception e) {
    42→                    log.error("Failed to save frame: {}", frame.getFrameId(), e);
    43→                    allErrors.add(new CsvRowError(0, frame.getFrameId(), "Failed to save: " + e.getMessage()));
    44→                }
    45→            }
    46→        }
    47→
    48→        log.info("CSV upload complete: inserted={}, skipped={}, errors={}", insertedCount, skippedCount, allErrors.size());
    49→
    50→        return CsvUploadResult.builder()
    51→                .totalRows(totalRows)
    52→                .insertedCount(insertedCount)
    53→                .skippedCount(skippedCount)
    54→                .errorCount(allErrors.size())
    55→                .errors(allErrors)
    56→                .build();
    57→    }
    58→}
