package com.global.ct.frameinventory.integration;

import com.global.ct.frameinventory.csv.CsvUploadResult;
import com.global.ct.frameinventory.frame.Action;
import com.global.ct.frameinventory.frame.Frame;
import com.global.ct.frameinventory.frame.FrameRepository;
import com.global.ct.frameinventory.frame.FrameRequest;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.client.TestRestTemplate;
import org.springframework.core.io.ByteArrayResource;
import org.springframework.http.*;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.util.LinkedMultiValueMap;
import org.springframework.util.MultiValueMap;
import org.testcontainers.containers.MongoDBContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
@Testcontainers
class FrameApiIntegrationTest {

    @Container
    static MongoDBContainer mongoDBContainer = new MongoDBContainer("mongo:7.0");

    @DynamicPropertySource
    static void setProperties(DynamicPropertyRegistry registry) {
        registry.add("spring.data.mongodb.uri", mongoDBContainer::getReplicaSetUrl);
    }

    @Autowired
    private TestRestTemplate restTemplate;

    @Autowired
    private FrameRepository frameRepository;

    @BeforeEach
    void setUp() {
        frameRepository.deleteAll();
    }

    @Test
    void createAndGetFrame() {
        // Create frame
        FrameRequest request = new FrameRequest();
        request.setFrameId("FRAME001");
        request.setType("DIGITAL");
        request.setFormat("D6");
        request.setEnvironment("UNDERGROUND");
        request.setStatus("LIVE");

        ResponseEntity<Frame> createResponse = restTemplate.postForEntity(
                "/api/frames", request, Frame.class);

        assertThat(createResponse.getStatusCode()).isEqualTo(HttpStatus.CREATED);
        assertThat(createResponse.getBody()).isNotNull();
        assertThat(createResponse.getBody().getFrameId()).isEqualTo("FRAME001");

        // Get frame
        ResponseEntity<Frame> getResponse = restTemplate.getForEntity(
                "/api/frames/FRAME001", Frame.class);

        assertThat(getResponse.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(getResponse.getBody()).isNotNull();
        assertThat(getResponse.getBody().getFrameId()).isEqualTo("FRAME001");
        assertThat(getResponse.getBody().getType()).isEqualTo("DIGITAL");
        assertThat(getResponse.getBody().getHistory()).hasSize(1);
        assertThat(getResponse.getBody().getHistory().get(0).getAction()).isEqualTo("CREATE");
    }

    @Test
    void updateFrame_recordsHistory() {
        // Create frame first
        FrameRequest createRequest = new FrameRequest();
        createRequest.setFrameId("FRAME002");
        createRequest.setType("DIGITAL");
        createRequest.setStatus("DRAFT");

        restTemplate.postForEntity("/api/frames", createRequest, Frame.class);

        // Update frame
        FrameRequest updateRequest = new FrameRequest();
        updateRequest.setFrameId("FRAME002");
        updateRequest.setType("DIGITAL");
        updateRequest.setStatus("LIVE");

        ResponseEntity<Frame> updateResponse = restTemplate.exchange(
                "/api/frames/FRAME002",
                HttpMethod.PUT,
                new HttpEntity<>(updateRequest),
                Frame.class);

        assertThat(updateResponse.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(updateResponse.getBody()).isNotNull();
        assertThat(updateResponse.getBody().getStatus()).isEqualTo("LIVE");

        // Verify history was recorded
        ResponseEntity<Frame> getResponse = restTemplate.getForEntity(
                "/api/frames/FRAME002", Frame.class);

        assertThat(getResponse.getBody()).isNotNull();
        assertThat(getResponse.getBody().getHistory()).hasSize(2);

        var updateEntry = getResponse.getBody().getHistory().stream()
                .filter(h -> h.getAction().equals("UPDATE"))
                .findFirst()
                .orElseThrow();

        assertThat(updateEntry.getChanges()).hasSize(1);
        assertThat(updateEntry.getChanges().get(0).getField()).isEqualTo("status");
        assertThat(updateEntry.getChanges().get(0).getOldValue()).isEqualTo("DRAFT");
        assertThat(updateEntry.getChanges().get(0).getNewValue()).isEqualTo("LIVE");
    }

    @Test
    void getFrame_returns404_whenNotFound() {
        ResponseEntity<String> response = restTemplate.getForEntity(
                "/api/frames/NONEXISTENT", String.class);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);
        assertThat(response.getBody()).contains("Frame not found");
    }

    @Test
    void uploadCsv_insertsFrames() {
        String csvContent = "frame_id,type_classic_digital,status,format,environment\n" +
                "CSV001,DIGITAL,LIVE,D6,UNDERGROUND\n" +
                "CSV002,CLASSIC,DRAFT,48,ROADSIDE\n";

        ResponseEntity<CsvUploadResult> response = uploadCsv(csvContent);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isNotNull();
        assertThat(response.getBody().getTotalRows()).isEqualTo(2);
        assertThat(response.getBody().getInsertedCount()).isEqualTo(2);
        assertThat(response.getBody().getErrorCount()).isEqualTo(0);

        // Verify frames exist in database
        List<Frame> frames = frameRepository.findAll();
        assertThat(frames).hasSize(2);
        assertThat(frames).extracting(Frame::getFrameId).containsExactlyInAnyOrder("CSV001", "CSV002");
    }

    @Test
    void uploadCsv_skipsExistingFrames() {
        // Create existing frame
        FrameRequest existingFrame = new FrameRequest();
        existingFrame.setFrameId("EXISTING001");
        existingFrame.setType("DIGITAL");
        existingFrame.setStatus("LIVE");
        restTemplate.postForEntity("/api/frames", existingFrame, Frame.class);

        // Upload CSV with existing and new frame
        String csvContent = "frame_id,type_classic_digital,status\n" +
                "EXISTING001,CLASSIC,DRAFT\n" +
                "NEW001,DIGITAL,LIVE\n";

        ResponseEntity<CsvUploadResult> response = uploadCsv(csvContent);

        assertThat(response.getStatusCode()).isEqualTo(HttpStatus.OK);
        assertThat(response.getBody()).isNotNull();
        assertThat(response.getBody().getTotalRows()).isEqualTo(2);
        assertThat(response.getBody().getInsertedCount()).isEqualTo(1);
        assertThat(response.getBody().getSkippedCount()).isEqualTo(1);

        // Verify existing frame was not modified
        ResponseEntity<Frame> existingResponse = restTemplate.getForEntity(
                "/api/frames/EXISTING001", Frame.class);
        assertThat(existingResponse.getBody()).isNotNull();
        assertThat(existingResponse.getBody().getType()).isEqualTo("DIGITAL"); // Original value, not CLASSIC
    }

    @Test
    void deleteFrame_removesFromDatabase() {
        // Create frame
        FrameRequest request = new FrameRequest();
        request.setFrameId("TO_DELETE");
        request.setType("DIGITAL");
        request.setStatus("LIVE");
        restTemplate.postForEntity("/api/frames", request, Frame.class);

        // Verify it exists
        assertThat(frameRepository.findByFrameId("TO_DELETE")).isPresent();

        // Delete frame
        ResponseEntity<Void> deleteResponse = restTemplate.exchange(
                "/api/frames/TO_DELETE",
                HttpMethod.DELETE,
                null,
                Void.class);

        assertThat(deleteResponse.getStatusCode()).isEqualTo(HttpStatus.NO_CONTENT);

        // Verify it's gone
        assertThat(frameRepository.findByFrameId("TO_DELETE")).isEmpty();
    }

    private ResponseEntity<CsvUploadResult> uploadCsv(String csvContent) {
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.MULTIPART_FORM_DATA);

        MultiValueMap<String, Object> body = new LinkedMultiValueMap<>();
        body.add("file", new ByteArrayResource(csvContent.getBytes()) {
            @Override
            public String getFilename() {
                return "test.csv";
            }
        });

        HttpEntity<MultiValueMap<String, Object>> requestEntity = new HttpEntity<>(body, headers);

        return restTemplate.postForEntity("/api/frames/upload", requestEntity, CsvUploadResult.class);
    }
}

