import type { Frame, FrameRequest, CsvUploadResult } from '../types/frame';

const API_BASE = '/api/frames';

export async function getFrames(): Promise<Frame[]> {
  const response = await fetch(API_BASE);
  if (!response.ok) {
    throw new Error(`Failed to fetch frames: ${response.status}`);
  }
  return response.json();
}

export async function getFrame(frameId: string): Promise<Frame> {
  const response = await fetch(`${API_BASE}/${frameId}`);
  if (!response.ok) {
    throw new Error(`Failed to fetch frame: ${response.status}`);
  }
  return response.json();
}

export async function createFrame(request: FrameRequest): Promise<Frame> {
  const response = await fetch(API_BASE, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    throw new Error(`Failed to create frame: ${response.status}`);
  }
  return response.json();
}

export async function updateFrame(frameId: string, request: FrameRequest): Promise<Frame> {
  const response = await fetch(`${API_BASE}/${frameId}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
  });
  if (!response.ok) {
    throw new Error(`Failed to update frame: ${response.status}`);
  }
  return response.json();
}

export async function deleteFrame(frameId: string): Promise<void> {
  const response = await fetch(`${API_BASE}/${frameId}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    throw new Error(`Failed to delete frame: ${response.status}`);
  }
}

export async function uploadCsv(file: File): Promise<CsvUploadResult> {
  const formData = new FormData();
  formData.append('file', file);

  const response = await fetch(`${API_BASE}/upload`, {
    method: 'POST',
    body: formData,
  });
  if (!response.ok) {
    throw new Error(`Failed to upload CSV: ${response.status}`);
  }
  return response.json();
}

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { getFrame } from '../api/frames';
import type { Frame, FrameHistoryEntry } from '../types/frame';

export function FrameDetailPage() {
  const { frameId } = useParams<{ frameId: string }>();
  const [frame, setFrame] = useState<Frame | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!frameId) return;

    getFrame(frameId)
      .then(setFrame)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [frameId]);

  function formatDateTime(dateString: string): string {
    const date = new Date(dateString);
    return date.toLocaleString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  function getStatusChipClass(status: string): string {
    switch (status.toUpperCase()) {
      case 'LIVE':
        return 'chip success';
      case 'DRAFT':
        return 'chip neutral';
      case 'PENDING':
        return 'chip warning';
      case 'INACTIVE':
        return 'chip error';
      default:
        return 'chip neutral';
    }
  }

  function getTimelineItemClass(entry: FrameHistoryEntry): string {
    return entry.action === 'CREATE' ? 'tl-item create' : 'tl-item';
  }

  function getActionVerb(action: string): string {
    return action === 'CREATE' ? 'created this frame' : 'updated this frame';
  }

  if (loading) {
    return (
      <div className="page">
        <p>Loading frame...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="page">
        <p className="error-text">Error: {error}</p>
        <Link to="/" className="btn outlined mt-2">
          Back to list
        </Link>
      </div>
    );
  }

  if (!frame) {
    return (
      <div className="page">
        <p>Frame not found</p>
        <Link to="/" className="btn outlined mt-2">
          Back to list
        </Link>
      </div>
    );
  }

  const sortedHistory = [...frame.history].sort(
    (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
  );

  return (
    <div className="page">
      <header className="page-header">
        <div>
          <Link to="/" className="back-link">
            ← Back to frames
          </Link>
          <h1 className="page-title-inline">
            <span className="id">{frame.frameId}</span>
            <span className={getStatusChipClass(frame.status)}>
              <span className="dot"></span>
              {frame.status}
            </span>
          </h1>
        </div>
        <Link to={`/frames/${frame.frameId}/edit`} className="btn primary">
          Edit frame
        </Link>
      </header>

      <div className="surface">
        <div className="section-block">
          <h2>Details</h2>
          <div className="kv">
            <div>
              <span className="k">Frame ID</span>
              <span className="v mono">{frame.frameId}</span>
            </div>
            <div>
              <span className="k">Type</span>
              <span className="v">{frame.type}</span>
            </div>
            <div>
              <span className="k">Format</span>
              <span className={`v ${!frame.format ? 'muted' : ''}`}>
                {frame.format || '—'}
              </span>
            </div>
            <div>
              <span className="k">Environment</span>
              <span className={`v ${!frame.environment ? 'muted' : ''}`}>
                {frame.environment || '—'}
              </span>
            </div>
            <div>
              <span className="k">Status</span>
              <span className="v">{frame.status}</span>
            </div>
            <div>
              <span className="k">Created</span>
              <span className="v mono">{formatDateTime(frame.createdDate)}</span>
            </div>
            <div>
              <span className="k">Last Modified</span>
              <span className="v mono">{formatDateTime(frame.modifiedDate)}</span>
            </div>
          </div>
        </div>

        <div className="section-block">
          <h2>History</h2>
          {sortedHistory.length === 0 ? (
